INSERT INTO `faqs` (`id`, `question`, `answer`, `category_id`, `sort_order`, `status`, `publish_at`, `published_at`, `reviewed_by`, `created_by`, `updated_by`, `created_at`, `updated_at`, `archived_at`) VALUES (1,'How do I submit a concern to the help desk?','Open the Help Desk page, fill in the form and submit it. You will see a ticket number and an access key. Save both to follow up on your concern.',30,0,'published',NULL,'2026-10-17 09:50:35',NULL,11,NULL,'2026-10-17 10:30:13',NULL,NULL),
(2,'I lost my access key. What should I do?','Submit a new concern and mention your earlier ticket number in the details. The help desk will link the two tickets.',30,1,'published',NULL,'2026-10-17 10:01:57',NULL,11,NULL,'2026-10-17 10:01:34',NULL,NULL),
(3,'Who can see a confidential concern?','Only help desk officers who are specifically authorized to handle confidential concerns, and the officer assigned to the ticket.',30,2,'published',NULL,'2026-10-17 10:39:41',NULL,11,NULL,'2026-10-17 10:17:01',NULL,NULL),
(4,'How can our cooperative appear in the cooperative directory?','Cooperatives are listed after their registration details are verified and they agree to be listed. Send a request through the help desk under \"Registration and Records Update\".',29,3,'published',NULL,'2026-10-17 10:16:00',NULL,11,NULL,'2026-10-17 10:02:26',NULL,NULL),
(5,'How do I register for an event?','Open the event page and use the registration form. When an event is full, you can join the waiting list.',29,4,'published',NULL,'2026-10-17 10:06:16',NULL,11,NULL,'2026-10-17 09:59:29',NULL,NULL),
(6,'Is cooperative membership treated as political support?','No. Membership in a cooperative is never treated as political affiliation or support, and no voter profiles are created.',31,5,'published',NULL,'2026-10-17 10:30:59',NULL,11,NULL,'2026-10-17 10:30:45',NULL,NULL),
(7,'How do I ask for a copy or correction of my personal data?','Use the Data Privacy Request form linked from the Privacy Notice. You will receive a reference number.',31,6,'published',NULL,'2026-10-17 09:53:44',NULL,11,NULL,'2026-10-17 09:53:49',NULL,NULL);
