INSERT INTO `pages` (`id`, `slug`, `title`, `summary`, `body`, `is_system`, `show_in_footer`, `status`, `publish_at`, `published_at`, `reviewed_by`, `created_by`, `updated_by`, `created_at`, `updated_at`, `archived_at`) VALUES (1,'about-us','About Us','Who we are and what we do (sample content).','<p>COOP NATCCO Partylist represents the cooperative sector. This sample profile shows how the About page presents the organization, its purpose and its work with primary cooperatives across the country.</p><h2>What we do</h2><ul><li>Legislative work for the cooperative sector</li><li>Assistance to primary cooperatives through the help desk</li><li>Partnerships, programs and capacity building</li></ul><p>Replace this text with the approved official profile.</p>',1,0,'published',NULL,'2026-01-20 10:29:35',NULL,1,NULL,'2026-11-15 00:00:00',NULL,NULL),
(2,'history','COOP NATCCO History','Establishment, milestones and achievements (sample content).','<p>This sample introduction shows where the verified history of COOP NATCCO Partylist will appear. The timeline below lists milestones, each with its source.</p>',1,0,'published',NULL,'2026-01-20 10:16:52',NULL,1,NULL,'2026-11-15 00:00:00',NULL,NULL),
(3,'privacy-notice','Privacy Notice','How we process personal information under the Data Privacy Act of 2012.','<h2>Who we are</h2><p>This notice explains how COOP NATCCO Partylist (\"we\") processes personal information collected through this website and its national database system, in line with the Data Privacy Act of 2012 (Republic Act No. 10173), its Implementing Rules and Regulations, and issuances of the National Privacy Commission.</p>\n<h2>What we collect and why</h2><ul><li><strong>Help desk concerns:</strong> your name, email address, optional phone number, cooperative and region, and the details of your concern, so we can respond to it. Attachments you upload are used only to resolve the concern.</li><li><strong>Event registrations:</strong> your name, email address, optional phone number and organization, so we can manage attendance and send event updates.</li><li><strong>Contact form messages:</strong> your name, email address and message, so we can reply.</li><li><strong>Privacy requests:</strong> your name, email address and request details, so we can act on your request.</li><li><strong>Cooperative records:</strong> authorized officers, staff, point persons and members of participating primary cooperatives, processed only for organizational coordination under the lawful basis recorded for each record.</li></ul>\n<p>Cooperative membership is never treated as political affiliation or support, and we do not create voter profiles or predict political preferences.</p>\n<h2>How we protect it</h2><p>Personal information is stored in access-controlled systems. Contact details are encrypted, access is limited by role and geographic scope, and access to sensitive records is logged.</p>\n<h2>How long we keep it</h2><p>We keep personal information only for as long as needed for the purpose it was collected for, following our approved retention schedule, and then dispose of it securely.</p>\n<h2>Your rights</h2><p>You may request access to, correction of, or deletion of your personal information, object to its processing, and lodge a complaint with the National Privacy Commission. Use the <a href=\"privacy-request.php\">Data Privacy Request form</a> to exercise these rights.</p>\n<h2>Cookies</h2><p>This website uses a single session cookie that is needed for forms and secure sign-in. We do not use advertising or tracking cookies.</p>',1,1,'published',NULL,'2026-11-15 00:00:00',NULL,1,NULL,'2026-11-15 00:00:00',NULL,NULL),
(4,'terms-of-use','Terms of Use','Conditions for using this website.','<h2>Use of this website</h2><p>By using this website you agree to use it lawfully and not to interfere with its operation or security.</p>\n<h2>Content</h2><p>Information on this website is provided for public information. Official documents, legislative records and election figures show their source and verification status. Organizational commentary is labeled as such.</p>\n<h2>Accounts</h2><p>Access to the national database system is limited to authorized users. Accounts are personal and must not be shared. Activity in the system is logged.</p>\n<h2>Links to other websites</h2><p>We are not responsible for the content of external websites linked from this website.</p>\n<h2>Changes</h2><p>We may update these terms. The current version is always available on this page.</p>',1,1,'published',NULL,'2026-11-15 00:00:00',NULL,1,NULL,'2026-11-15 00:00:00',NULL,NULL),
(5,'accessibility-statement','Accessibility Statement','Our commitment to an accessible website.','<p>We want this website to be usable by everyone, including people who use assistive technologies.</p>\n<h2>Our approach</h2><ul><li>We follow the Web Content Accessibility Guidelines (WCAG) 2.2 at level AA as our design target.</li><li>All pages can be used with a keyboard, and focused elements show a visible outline.</li><li>Text and interface colors are chosen for readable contrast.</li><li>Images that carry information have text alternatives.</li><li>Forms have labels, clear instructions and error messages.</li><li>Pages adapt to phones, tablets and desktop screens and support browser zoom.</li></ul>\n<h2>Feedback</h2><p>If you have difficulty using any part of this website, please tell us through the <a href=\"contact.php\">contact page</a> or the <a href=\"helpdesk.php\">help desk</a>, and we will provide the information in another way.</p>',1,1,'published',NULL,'2026-11-15 00:00:00',NULL,1,NULL,'2026-11-15 00:00:00',NULL,NULL);
