(2,'news',1,NULL,'help-desk-for-primary-cooperatives-now-accepts-online-concerns','Help desk for primary cooperatives now accepts online concerns','Primary cooperatives can now submit concerns online, receive a ticket number and follow up without visiting an office.','<p>This is sample content written to demonstrate the publishing workflow. It shows how news, announcements and other updates appear on the public website.</p><h2>Highlights</h2><ul><li>Participants from several primary cooperatives</li><li>Discussion of common concerns and proposals</li><li>Agreed follow-up actions with timelines</li></ul><p>Replace this sample with official, approved content before going live.</p>',2,NULL,NULL,'Communications Office',1,412,'published',NULL,'2026-11-12 10:14:55',11,11,NULL,'2026-11-12 10:14:55',NULL,NULL),
